/* 验收/终止表单与历史快照绑定，HTML独立维护；所有命令通过模拟接口。 */
window.EamMaintenanceClosureUi=(()=>{const $=id=>document.getElementById(id),ui=EamUiComponents;let task,config,onChanged,isDirty,action,busy=false,page=1,initialized=false;
const labels={acceptance:'独立保养验收','request-termination':'申请终止','review-termination':'获取外部审批结果'},decision={passed:'通过',returned:'退回',approved:'外部通过',rejected:'未批准',pending_review:'待审批',pending:'待审批',withdrawn:'已撤回'};
const person=id=>id==='external-service'?'外部审批服务':config.followupPeople.find(p=>p.id===id)?.name||config.people.find(p=>p.id===id)?.name||id||'—';
function facts(host,entries){host.replaceChildren();for(const [name,value]of entries){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value||'—';host.append(dt,dd);}}
function snapshot(row){$('mc-snapshot-title').textContent=row.type+' · 执行V'+row.version;const r=row.record,e=r.submission||r.executionSnapshot||r;facts($('mc-snapshot-summary'),[['状态 / 决定',row.state],['原始试运行',e.trial],['工时（分钟）',String(e.laborMinutes??'—')],['用料引用',e.materialRef],['审核 / 提交意见',r.reason],['验收证据',r.evidence],['异常评审',r.residualReview],['遗留风险',r.residualRisk],['控制措施',r.controlMeasures],['后续安排',r.followup],['后续责任人',r.followupOwnerId?person(r.followupOwnerId):'—'],['安排期限',r.followupDueAt],['终止审核意见',r.reviewReason]]);function draw(p=1){$('mc-snapshot-results').replaceChildren();for(const result of (e.results||[]).slice((p-1)*8,p*8)){const tr=document.createElement('tr');for(const value of [task.snapshot.items.find(i=>i.id===result.itemId)?.name||result.itemId,(result.conclusion==='normal'?'正常':'异常')+(result.value!==undefined&&result.value!==''?' / '+result.value:''),result.evidence,result.followup,person(result.actorId)]){const td=document.createElement('td');td.textContent=value||'—';tr.append(td);}$('mc-snapshot-results').append(tr);}ui.decorateTables();ui.setTableStatus('mc-snapshot-results','loaded');ui.pagination($('mc-snapshot-pagination'),{page:p,pages:Math.max(1,Math.ceil((e.results||[]).length/8)),total:(e.results||[]).length,pageSize:8,onChange:draw});}draw();$('mc-snapshot-dialog').showModal();}
function history(){const submissions=task.submissions?.length?task.submissions:task.submission?[task.submission]:[],rows=[...submissions.map(s=>({type:'执行提交',version:s.executionVersion,state:'已提交',actor:s.submittedBy,at:s.submittedAt,record:s})),...(task.acceptances||[]).map(a=>({type:'独立验收',version:a.executionVersion,state:decision[a.decision],actor:a.reviewerId,at:a.reviewedAt,record:a})),...(task.terminationRequests||[]).map(r=>({type:'终止申请 / 审核',version:r.executionVersion,state:decision[r.status],actor:r.externalStatus&&r.externalStatus!=='pending'?'external-service':r.reviewedBy||r.requestedBy,at:r.reviewedAt||r.requestedAt,record:r}))].filter(r=>[r.type,'V'+r.version,r.state,r.record.reason,r.record.reviewReason].join(' ').includes($('mc-history-search').value));rows.sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));page=Math.min(page,Math.max(1,Math.ceil(rows.length/5)));$('mc-history').replaceChildren();for(const row of rows.slice((page-1)*5,page*5)){const tr=document.createElement('tr');for(const value of [row.type,'V'+row.version,row.state,person(row.actor),EamProduct.time(row.at),row.record.reviewReason||row.record.reason]){const td=document.createElement('td');td.textContent=value||'—';tr.append(td);}const td=document.createElement('td'),b=document.createElement('button');b.className='btn btn-sm btn-outline-primary';b.textContent='查看快照';b.onclick=()=>snapshot(row);td.append(b);tr.append(td);$('mc-history').append(tr);}ui.decorateTables();ui.setTableStatus('mc-history','loaded');ui.pagination($('mc-history-pagination'),{page,pages:Math.max(1,Math.ceil(rows.length/5)),total:rows.length,pageSize:5,onChange:p=>{page=p;history();}});}
function requirements(){const pass=action==='acceptance'&&$('mc-acceptance-decision').value==='passed';$('mc-items-verified').required=pass;$('mc-trial-verified').required=pass;$('mc-acceptance-evidence').required=pass;$('mc-residual-review').required=pass&&!!task.anomalyLinks.length;$('mc-termination-confirmed').required=false;}
function open(command){if(busy||isDirty()){Eam.message('请先暂存执行输入，再进行审核或申请');return;}action=command;$('mc-form').reset();$('mc-reason').required=action!=='review-termination';$('mc-reason').closest('label').hidden=action==='review-termination';$('mc-error').textContent='';$('mc-title').textContent=labels[action];$('mc-context').textContent=task.code+' · 数据V'+task.revision+' · 执行V'+task.executionVersion+(action==='acceptance'?'；技术验收须独立于执行参与者。':'；审批结果来自外部服务，EAM只处理业务生效。');for(const [id,visible]of [['mc-acceptance-fields',action==='acceptance'],['mc-termination-fields',action==='request-termination'],['mc-termination-review-fields',action==='review-termination']]){const host=$(id);host.hidden=!visible;for(const control of host.querySelectorAll('input,select,textarea'))control.disabled=!visible;}for(const id of ['mc-completed-work','mc-residual-risk','mc-controls','mc-followup','mc-owner','mc-due','mc-termination-evidence'])$(id).required=action==='request-termination';$('mc-owner').replaceChildren(new Option('请选择责任人',''),...config.followupPeople.map(p=>new Option(p.name,p.id)));if(action==='review-termination'){const r=task.termination;facts($('mc-request-summary'),[['外部实例',r.instanceId],['审批状态',decision[r.externalStatus||r.status]||r.status],['申请人',person(r.requestedBy)],['申请原因',r.reason],['已完成工作',r.completedWork],['遗留风险',r.residualRisk],['控制措施',r.controlMeasures],['后续安排',r.followup],['责任人',person(r.followupOwnerId)],['安排期限',r.followupDueAt],['申请证据',r.evidence]]);}requirements();$('mc-dialog').showModal();}
function initialize(){if(initialized)return;initialized=true;$('mc-history-search').oninput=()=>{page=1;history();};$('mc-acceptance-decision').onchange=requirements;$('mc-termination-decision').onchange=requirements;$('mc-cancel').onclick=()=>{if(!busy)$('mc-dialog').close();};$('mc-dialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('mc-snapshot-close').onclick=()=>$('mc-snapshot-dialog').close();$('mc-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('mc-submit').disabled=true;$('mc-cancel').disabled=true;try{const body={expectedRevision:task.revision,executionVersion:task.executionVersion,reason:action==='review-termination'?'获取外部审批结果':$('mc-reason').value};if(action==='acceptance')Object.assign(body,{decision:$('mc-acceptance-decision').value,itemsVerified:$('mc-items-verified').checked,trialVerified:$('mc-trial-verified').checked,evidence:$('mc-acceptance-evidence').value,residualReview:$('mc-residual-review').value});if(action==='request-termination')Object.assign(body,{completedWork:$('mc-completed-work').value,residualRisk:$('mc-residual-risk').value,controlMeasures:$('mc-controls').value,followup:$('mc-followup').value,followupOwnerId:$('mc-owner').value,followupDueAt:$('mc-due').value,evidence:$('mc-termination-evidence').value});if(action==='review-termination')Object.assign(body,{terminationRevision:task.termination.revision,instanceId:task.termination.instanceId,sample:$('mc-termination-decision').value});if(action==='review-termination')await EamMaintenanceApi.request('GET','/maintenance/tasks/'+encodeURIComponent(task.id)+'/approval-result',body);const result=await EamMaintenanceApi.request('POST','/maintenance/tasks/'+encodeURIComponent(task.id)+'/'+(action==='review-termination'?'apply-approval-result':action),body);$('mc-dialog').close();onChanged(result);Eam.message('审核或申请已保存');}catch(error){$('mc-error').textContent=error.message+'；输入已保留';}finally{busy=false;$('mc-submit').disabled=false;$('mc-cancel').disabled=false;}};}
return {bind(record,c,changed,dirty){task=record;config=c;onChanged=changed;isDirty=dirty;initialize();for(const [command,label]of Object.entries(labels))if(task.actions[command]){const b=document.createElement('button');b.className='btn btn-sm '+(command==='request-termination'?'btn-outline-danger':'btn-primary');b.textContent=label;b.onclick=()=>open(command);$('mt-actions').append(b);}history();}};})();
